(async () => {
 const root=document.getElementById('root'),field=document.getElementById('newsContent'),rich=WebWindowsNewsContent,editor=WebWindowsAdminRichText.create(root,field),instance=Jodit.instances.newsContent;let count=0;
 const check=(value,name)=>{if(!value)throw Error(name);count++;};
 const select=node=>{instance.s.select(node || instance.editor,true);instance.s.focus();};
 const tick=()=>new Promise(resolve=>setTimeout(resolve,400));
 try {
  check(!!instance && root.querySelectorAll('.jodit-container').length===1,'one Jodit instance');check(!root.querySelector('.ww-rich-toolbar'),'no custom toolbar');check(Jodit.version==='4.15.14','pinned version');
  editor.setContent('<h2>完整正文</h2><p>读取最新中文内容</p>');editor.setEnabled(true);check(!!instance.editor.querySelector('h2'),'detail title format');check(editor.getContent().includes('读取最新中文内容'),'detail body');
  editor.setContent('<p>排版测试</p>');select(instance.editor.querySelector('p'));instance.execCommand('bold');await tick();check(/<(strong|b)>/.test(editor.getContent()),'native bold');instance.execCommand('undo');await tick();check(!/<(strong|b)>/.test(editor.getContent()),'native undo');instance.execCommand('redo');await tick();check(/<(strong|b)>/.test(editor.getContent()),'native redo');
  select(instance.editor.querySelector('p'));instance.execCommand('fontname',false,'Georgia');instance.execCommand('fontsize',false,'24');instance.execCommand('forecolor',false,'#123456');instance.execCommand('justifycenter');await tick();const styles=editor.getContent();check(/font-family:Georgia/.test(styles),'native font');check(/font-size:24px/.test(styles),'native size');check(/color:(#123456|rgb\(18, 52, 86\))/.test(styles),'native color');check(/text-align:center/.test(styles),'native alignment');
  editor.setContent('<p>表格内容</p><table style="border-collapse:collapse;width:80.25%"><tbody><tr><td style="width:50%;border:1px solid #123456;vertical-align:middle;background-color:#abcdef">表格</td><td>第二列</td></tr></tbody></table><img src="https://example.com/a.png" alt="测试图" style="width:300px;height:200px">');let saved=editor.getContent();check(/width:80.25%/.test(saved),'table width preserved');check(/vertical-align:middle/.test(saved),'cell alignment');check(/border:1px solid/.test(saved),'cell border');check(/width:300px;height:200px/.test(saved),'image size');editor.setContent('');editor.setContent(saved);check(editor.getContent().includes('第二列')&&!!instance.editor.querySelector('img'),'save/reopen');
  instance.setMode(Jodit.MODE_SOURCE);await tick();check(instance.getMode()===Jodit.MODE_SOURCE,'native source mode');instance.value='<h3>源码正文</h3><script>evil()</script><p onclick="evil()" style="position:fixed;color:#123456">安全样式</p><img src="data:x"><a href="javascript:x">链接</a>';instance.setMode(Jodit.MODE_WYSIWYG);await tick();check(!!instance.editor.querySelector('h3'),'source visual heading');check(!instance.editor.querySelector('script,[onclick],img[src^="data:"],a[href^="javascript:"]'),'source clean');check(/color:#123456/.test(editor.getContent())&&!/position:/.test(editor.getContent()),'source style clean');
  editor.setContent('第一行\n第二行');check(instance.editor.textContent.includes('第一行\n第二行'),'legacy plain lines');editor.setContent('<p>正文</p>');editor.setEnabled(false);check(instance.o.readonly===true,'loading readonly');editor.setEnabled(true);check(instance.o.readonly===false,'loaded writable');
  check(instance.o.sourceEditor==='area'&&!instance.o.sourceEditorCDNUrlsJS.length,'no source CDN');check(!instance.o.uploader.url&&!instance.o.uploader.insertImageAsBase64URI&&!instance.o.uploader.showTabInFileSelector,'no upload');
  editor.setContent('<h2>Jodit 4.15.14 富文本编辑器</h2><p>官方免费 MIT 控件，使用本地 JS/CSS。</p><p><span style="font-family:Georgia;font-size:24px;color:#2563eb">正文与格式可以完整保存和再次加载。</span></p><table style="width:100%;border-collapse:collapse"><tbody><tr><th>功能</th><th>实现</th></tr><tr><td>工具栏 / 源码 / 历史</td><td>Jodit 原生控件</td></tr><tr><td>正文保护</td><td>完整详情读取、服务端安全清洗</td></tr></tbody></table>');
  document.getElementById('result').textContent=`PASS ${count}：Jodit 初始化、原生排版/撤销/源码、格式保留、正文再加载、安全清洗与本地资源配置通过`;
 } catch(error){document.getElementById('result').textContent='FAIL '+error.stack;}
})();
